const __pageData = JSON.parse('{"title":"SpringBoot配置优先级与Bean管理","description":"第 14 章（SpringBoot 原理篇）的开篇——先把「同一项配置写在不同地方，到底谁说了算」讲清楚（三种配置文件格式、Java 系统属性、命令行参数，附本机 8081 / 9000 / 10010 三行实测），再回到 Bean 管理本身：五种作用域与延迟初始化、第三方对象为什么要用 @Bean 加 @Configuration 集中声明，并顺手把连接信息与打包插件的规矩交代清楚","frontmatter":{"title":"SpringBoot配置优先级与Bean管理","published":"2026-09-29T00:00:00.000Z","description":"第 14 章（SpringBoot 原理篇）的开篇——先把「同一项配置写在不同地方，到底谁说了算」讲清楚（三种配置文件格式、Java 系统属性、命令行参数，附本机 8081 / 9000 / 10010 三行实测），再回到 Bean 管理本身：五种作用域与延迟初始化、第三方对象为什么要用 @Bean 加 @Configuration 集中声明，并顺手把连接信息与打包插件的规矩交代清楚","tags":["JavaWeb","SpringBoot","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-88-config-priority-bean.webp","order":88,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/88-SpringBoot配置优先级与Bean管理.md","filePath":"posts/学习文档/JavaWeb学习笔记/88-SpringBoot配置优先级与Bean管理.md"}');
